css:
[data-bz-section="pg-staff"] .bz-block { padding-block: 0; }
[data-bz-section="pg-staff"] .bz-headingblock h2 { font-size: 24px; margin: 0 0 28px; color: var(--ink); }
[data-bz-section="pg-staff"] .bz-col[data-bz-node^="pst-group"] { margin-bottom: 64px; }
[data-bz-section="pg-staff"] .bz-col[data-bz-node^="pst-group"]:last-child { margin-bottom: 0; }
/* Five across is not a divisor of the 12-column grid, so it is its own grid (same approach as pg-cards). */
[data-bz-section="pg-staff"] .bz-row:has(> .bz-col[data-bz-node^="pst-person"]) { grid-template-columns: repeat(5, minmax(0, 1fr)); column-gap: 28px; row-gap: 32px; }
[data-bz-section="pg-staff"] .bz-row > .bz-col[data-bz-node^="pst-person"] { grid-column: auto; }
[data-bz-section="pg-staff"] .bz-figure { margin: 0 0 12px; }
[data-bz-section="pg-staff"] .bz-figure img { display: block; width: 100%; aspect-ratio: 1; height: auto; object-fit: cover; object-position: top; border-radius: 6px; border: 1px solid #eee; background: #f0f0f0; }
[data-bz-section="pg-staff"] [data-bz-node^="pst-name"] p { margin: 0; font: 600 15px / 1.4 var(--font-body); color: var(--ink); }
[data-bz-section="pg-staff"] [data-bz-node^="pst-role"] p { margin: 0; font: italic 400 13px / 1.4 var(--font-body); color: var(--muted); }
@media (max-width: 1100px) { [data-bz-section="pg-staff"] .bz-row:has(> .bz-col[data-bz-node^="pst-person"]) { grid-template-columns: repeat(3, minmax(0, 1fr)); column-gap: 20px; } }
@media (max-width: 640px) { [data-bz-section="pg-staff"] .bz-row:has(> .bz-col[data-bz-node^="pst-person"]) { grid-template-columns: repeat(2, minmax(0, 1fr)); } [data-bz-section="pg-staff"] .bz-col[data-bz-node^="pst-group"] { margin-bottom: 44px; } }
